## Why This Is Asked
This question tests the ability to design an offline-first, real-time collaboration feature using the Canvas API, WebSocket communication, and Service Workers. It evaluates understanding of robust reconnection strategies, multi-client synchronization, and cross-tab coordination.

## Key Concepts
- Canvas rendering with minimal DOM manipulation; use a single render loop via requestAnimationFrame
- WebSocket-based real-time synchronization with an operation log and CRDT-like merge logic
- Service Worker caching for the app shell and board bitmap to enable offline use
- Cross-tab coordination via BroadcastChannel with resilient reconnect and exponential backoff strategies

## Code Example
```javascript
// WebSocket wrapper (connect, backoff, send, onMessage)
class WS {
  constructor(url) {
    this.url = url;
    this.ws = null;
    this.reconnectDelay = 1000;
    this.maxReconnectDelay = 30000;
    this.handlers = {};
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onopen = () => { this.reconnectDelay = 1000; };
    this.ws.onclose = () => this.reconnect();
    this.ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      this.handlers[msg.type]?.(msg.payload);
    };
  }

  reconnect() {
    setTimeout(() => {
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
      this.connect();
    }, this.reconnectDelay);
  }

  send(type, payload) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type, payload }));
    }
  }

  on(type, handler) {
    this.handlers[type] = handler;
  }
}

// opLog for CRDT-like merge
class OpLog {
  constructor() {
    this.ops = [];
    this.vectorClock = {};
  }

  addOp(op) {
    this.ops.push(op);
    this.vectorClock[op.clientId] = (this.vectorClock[op.clientId] || 0) + 1;
  }

  merge(remoteOps) {
    for (const op of remoteOps) {
      const dominated = this.ops.some(local =>
        local.clientId === op.clientId && local.timestamp <= op.timestamp
      );
      if (!dominated) {
        this.ops.push(op);
      }
    }
  }
}

// Service Worker (install/activate/cache)
// sw.js
self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open('whiteboard-v1').then(cache => cache.addAll(['/', '/index.html', '/app.js']))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== 'whiteboard-v1').map(k => caches.delete(k)))
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(cached => cached || fetch(e.request))
  );
});

// Main render wiring
const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const ws = new WS('ws://localhost:8080');
const opLog = new OpLog();

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const op of opLog.ops) {
    ctx.beginPath();
    ctx.moveTo(op.x1, op.y1);
    ctx.lineTo(op.x2, op.y2);
    ctx.stroke();
  }
  requestAnimationFrame(render);
}

canvas.addEventListener('mousemove', (e) => {
  if (e.buttons !== 1) return;
  const op = { x1: lastX, y1: lastY, x2: e.offsetX, y2: e.offsetY };
  opLog.addOp(op);
  ws.send('stroke', op);
  lastX = e.offsetX;
  lastY = e.offsetY;
});

ws.on('stroke', (op) => opLog.addOp(op));
ws.connect();
render();
```

## Why This Is Asked
Tests ability to implement a small, practical caching layer with closures, per-URL keys, in-flight request sharing, and TTL-based invalidation using Promises. It mirrors common frontend API client patterns at scale.

## Key Concepts
- Closures to encapsulate cache state
- Per-URL Map storage with {promise, expires}
- Concurrency control: share in-flight Promise across callers
- TTL-based invalidation and error handling for retries
- fetch API and parsing JSON safely

## Code Example
```javascript
function makeApiClient() {
  const cache = new Map();
  return {
    fetchWithCache: (url, ttlMs) => {
      const now = Date.now();
      const entry = cache.get(url);
      if (entry && now < entry.expires) {
        return entry.promise;
      }
      const promise = fetch(url).then(res => {
        if (!res.ok) throw new Error(res.statusText || res.status);
        return res.json();
      }).catch(err => {
        cache.delete(url);
        throw err;
      });
      cache.set(url, { promise, expires: ttlMs != null ? now + ttlMs : Number.POSITIVE_INFINITY });
      return promise;
    }
  };
}
```

